import { t as createApiClient } from "../../../../chunks/api.js";
//#region src/routes/(student)/student-dashboard/+page.server.ts
var load = async ({ locals }) => {
	const api = createApiClient(locals.token);
	const [disc, holland, papi, cfit, ist] = await Promise.allSettled([
		api.get("/disc/check"),
		api.get("/holland/check"),
		api.get("/papi/check"),
		api.get("/cfit/check"),
		api.get("/ist/check")
	]);
	function resolveStatus(result) {
		if (result.status === "rejected") return {
			available: false,
			completed: false
		};
		const v = result.value;
		if (!v || v.code) return {
			available: false,
			completed: false
		};
		return {
			available: v?.canTake ?? false,
			completed: false
		};
	}
	return { tests: [
		{
			key: "disc",
			label: "DISC",
			href: "/student-disc",
			...resolveStatus(disc)
		},
		{
			key: "holland",
			label: "Holland RIASEC",
			href: "/student-holland",
			...resolveStatus(holland)
		},
		{
			key: "papi",
			label: "PAPI Kostick",
			href: "/student-papi",
			...resolveStatus(papi)
		},
		{
			key: "cfit",
			label: "IQ CFIT",
			href: "/student-cfit",
			...resolveStatus(cfit)
		},
		{
			key: "ist",
			label: "IQ IST",
			href: "/student-ist",
			...resolveStatus(ist)
		}
	] };
};
//#endregion
export { load };
